WITH rollup_totals AS (SELECT d.region, COUNT(*) AS cnt, ROUND(SUM(src.quantity), 2) AS total_quantity, GROUPING_ID() AS gid FROM inventory src LEFT JOIN stores d ON src.store_id = d.id GROUP BY ROLLUP (d.region)) SELECT region, cnt, total_quantity, gid, CASE WHEN region RLIKE '^(North|Central)$' THEN 'CORE' ELSE 'GROUP_B' END AS region_zone FROM rollup_totals ORDER BY total_quantity ASC NULLS FIRST;
